// The item arriving here is the history table, not the config - the read sits
// between Settings and this node so the report can compare against it later.
const cfg = $('Settings').first().json || {};

function clean(raw) {
  return String(raw || '')
    .split(/[\s,]+/)
    .map((u) => u.trim())
    .filter(Boolean);
}

const you = clean(cfg.your_company_url);
const rivals = clean(cfg.competitor_urls);
const all = [...you, ...rivals];

if (all.length < 2) {
  throw new Error('Put your own Glassdoor reviews URL and at least one competitor in Settings.');
}

// The employer id is the part that goes wrong. A typo does not 404 quickly - it
// spends 90 seconds waiting for a selector that never appears, then retries.
const bad = all.filter((u) => !/\/Reviews\/.+-Reviews-E\d+\.htm/i.test(u));
if (bad.length) {
  throw new Error(`These do not look like Glassdoor reviews URLs: ${bad.join(', ')}`);
}

function employerId(u) {
  const m = String(u).match(/-E(\d+)\.htm/i);
  return m ? m[1] : '';
}

const days = Number(cfg.days_back) || 365;
const expected = all.map((u) => ({ url: u, employer_id: employerId(u) }));

// One crawl per company, not one crawl holding every company. The dataset caps
// a snapshot at 100 rows across all of its inputs, and whichever input finishes
// first takes the whole budget: measured 2026-09-13, two companies in one
// snapshot returned 100 rows for one of them and nothing at all for the other,
// with errors: 0. Sent one at a time each company gets its own hundred, which
// is what the comparison below assumes.
// The shared fields ride on every item so the report can still read the plan
// with .first() no matter which company came back.
return all.map((u) => ({
  json: {
    payload: [{ url: u, days }],
    url: u,
    employer_id: employerId(u),
    is_you: u === you[0],
    yours: employerId(you[0]),
    your_url: you[0],
    expected,
  },
}));

// single-item input: one company is in flight per pass of the loop, so this is
// one progress call and one answer.
const status = $input.first().json || {};
const cfg = $('Settings').first().json;

const state = String(status.status || 'unknown');

// The poll count rides on the item rather than coming from $runIndex. $runIndex
// counts every pass of this node in the run, and the batch loop re-enters it
// once per company - so a ceiling of 45 would already be spent partway through
// the third company and the rest would be reported as having no reviews. Wait
// passes through whatever reached it: the trigger response on the first poll,
// this node's own output on every one after.
const before = Number(($('Wait For The Crawl').first().json || {}).polls || 0);
const polls = before + 1;
// The ceiling is generous on purpose: a mistyped employer id took 598 seconds
// to fail, and cutting the loop short would report "no reviews" for what is
// really a bad URL.
const giveUp = polls >= (Number(cfg.max_polls) || 45);

return [{
  json: {
    state,
    records: Number(status.records) || 0,
    polls,
    give_up: giveUp,
    done: state === 'ready' || state === 'failed' || giveUp,
  },
}];

// The way back into the loop. A branch that ends in zero items never re-enters
// Split In Batches, so the run would stop after the first company with every
// node green - and an empty crawl is not rare here: the same valid employer
// URL returned 100, 100, 0 and 100 rows across four crawls in one hour. So
// `Download The Reviews` always outputs data, and a pass that found nothing
// comes back as a marker instead of nothing at all.
const here = $('Loop Over The Companies').first().json || {};

const rows = [];
for (const item of $input.all()) {
  const raw = item && item.json;
  if (!raw || typeof raw !== 'object') continue;
  // A failed input arrives as a row with an error and no review fields, and it
  // is worth keeping - the report names it rather than dropping it.
  if (!raw.rating_date && !raw.error && !raw.error_code) continue;
  rows.push(raw);
}

if (!rows.length) {
  return [{
    json: {
      empty: true,
      asked_for: String(here.url || ''),
      employer_id: String(here.employer_id || ''),
    },
  }];
}

return rows.map((r) => ({ json: r }));

const cfg = $('Settings').first().json;
const plan = $('Plan The Crawl').first().json || {};
const rows = $input.all().map((i) => i.json);

const DIMENSIONS = [
  ['rating_overall', 'Overall'],
  ['rating_compensation_benefits', 'Pay and benefits'],
  ['rating_culture_values', 'Culture and values'],
  ['rating_work_life', 'Work-life balance'],
  ['rating_senior_leadership', 'Senior leadership'],
  ['rating_career_opportunities', 'Career opportunities'],
  ['rating_diversity_inclusion', 'Diversity and inclusion'],
];

// Bright Data puts a failed input in the results array as a row with an error
// and no review fields, and it can come first.
const reviews = [];
const errors = [];
for (const raw of rows.flat()) {
  if (!raw || typeof raw !== 'object') continue;
  if (raw.error || raw.error_code) {
    errors.push(String(raw.error || raw.error_code).slice(0, 160));
    continue;
  }
  const when = Date.parse(raw.rating_date || '');
  if (!Number.isFinite(when)) continue;

  reviews.push({
    employer_id: String(raw.glassdoor_employer_id || raw.overview_id || ''),
    company: String(raw.company_name || 'unknown'),
    when_ms: when,
    when: new Date(when).toISOString().slice(0, 10),
    // employee_type is free text with eleven variants in a single sample, so a
    // prefix match is the only thing that holds.
    is_former: /^former/i.test(String(raw.employee_type || '')),
    pros: String(raw.review_pros || '').trim(),
    cons: String(raw.review_cons || '').trim(),
    summary: String(raw.summary || '').trim(),
    ceo_approval: raw.flags_ceo_approval || null,
    outlook: raw.flags_business_outlook || null,
    recommend: raw.flags_recommend_frend || null,
    ratings: Object.fromEntries(
      DIMENSIONS.map(([key]) => [key, raw[key] === null || raw[key] === undefined ? null : Number(raw[key])])
    ),
  });
}

const byCompany = new Map();
for (const r of reviews) {
  const list = byCompany.get(r.employer_id) || [];
  list.push(r);
  byCompany.set(r.employer_id, list);
}

// One hundred rows come back whatever `days` says, so each company's hundred
// covers a different span. The shared window is the latest start date across
// the set: the point from which every company has coverage.
const spans = [...byCompany.entries()].map(([id, list]) => ({
  id,
  company: list[0].company,
  oldest: Math.min(...list.map((r) => r.when_ms)),
  newest: Math.max(...list.map((r) => r.when_ms)),
  total: list.length,
}));

const missing = (plan.expected || []).filter(
  (e) => e.employer_id && !byCompany.has(e.employer_id)
);

if (!spans.length) {
  return [{
    json: {
      companies: [],
      comparable: false,
      window_from: '',
      window_to: '',
      errors,
      missing,
      reason: 'No company returned a single readable review.',
    },
  }];
}

const windowFrom = Math.max(...spans.map((s) => s.oldest));
const windowTo = Math.min(...spans.map((s) => s.newest));

function avg(list) {
  // Averaged over the reviews that answered this dimension, not over every
  // review. The sub-ratings are about 73% filled; dividing by the row count
  // would shave roughly a quarter off each one, evenly enough to look real.
  const answered = list.filter((v) => v !== null && Number.isFinite(v));
  if (!answered.length) return null;
  return Math.round((answered.reduce((a, b) => a + b, 0) / answered.length) * 100) / 100;
}

function share(list, positive) {
  const answered = list.filter((v) => v !== null && v !== undefined);
  if (!answered.length) return null;
  const hits = answered.filter((v) => positive.includes(String(v))).length;
  return { pct: Math.round((hits / answered.length) * 100), answered: answered.length };
}

const companies = spans.map((s) => {
  const all = byCompany.get(s.id) || [];
  const inWindow = all.filter((r) => r.when_ms >= windowFrom && r.when_ms <= windowTo);
  const current = inWindow.filter((r) => !r.is_former);
  const former = inWindow.filter((r) => r.is_former);

  const scores = {};
  for (const [key, label] of DIMENSIONS) {
    scores[key] = {
      label,
      all: avg(inWindow.map((r) => r.ratings[key])),
      current: avg(current.map((r) => r.ratings[key])),
      former: avg(former.map((r) => r.ratings[key])),
      answered: inWindow.filter((r) => r.ratings[key] !== null).length,
    };
  }

  return {
    employer_id: s.id,
    company: s.company,
    is_you: s.id === plan.yours,
    reviews_total: s.total,
    reviews_in_window: inWindow.length,
    current_count: current.length,
    former_count: former.length,
    span_from: new Date(s.oldest).toISOString().slice(0, 10),
    span_to: new Date(s.newest).toISOString().slice(0, 10),
    scores,
    ceo_approval: share(inWindow.map((r) => r.ceo_approval), ['APPROVE']),
    outlook_positive: share(inWindow.map((r) => r.outlook), ['POSITIVE']),
    would_recommend: share(inWindow.map((r) => r.recommend), ['POSITIVE']),
    worst_cons: inWindow
      .filter((r) => r.cons)
      .slice(0, 12)
      .map((r) => r.cons.replace(/\s+/g, ' ').slice(0, 200)),
  };
});

const you = companies.find((c) => c.is_you) || null;
const rivals = companies.filter((c) => !c.is_you);

// The gap worth acting on is the dimension where the distance between you and
// the best rival is widest, not the dimension where your own score is lowest.
const gaps = [];
if (you) {
  for (const [key, label] of DIMENSIONS) {
    const mine = you.scores[key].all;
    const theirs = rivals.map((r) => r.scores[key].all).filter((v) => v !== null);
    if (mine === null || !theirs.length) continue;
    const best = Math.max(...theirs);
    gaps.push({
      key,
      label,
      yours: mine,
      best_rival: best,
      best_rival_name: (rivals.find((r) => r.scores[key].all === best) || {}).company || '',
      gap: Math.round((best - mine) * 100) / 100,
    });
  }
  gaps.sort((a, b) => b.gap - a.gap);
}

const worst = gaps[0] || null;

return [{
  json: {
    companies,
    gaps,
    worst_gap: worst,
    comparable: Boolean(you) && rivals.length > 0,
    window_from: new Date(windowFrom).toISOString().slice(0, 10),
    window_to: new Date(windowTo).toISOString().slice(0, 10),
    errors,
    missing,
    reason: you ? '' : 'Your own company URL returned no reviews, so there is nothing to compare against.',
    cons_brief:
      worst && you
        ? you.worst_cons.map((c, i) => `${i + 1}. ${c}`).join('\n')
        : '',
    worst_label: worst ? worst.label : '',
  },
}];

// single-item input: the comparison above emits one object.
const data = $('Line Up The Windows').first().json || {};
const cfg = $('Settings').first().json;

let theme = '';
try {
  theme = String(($input.first().json || {}).text || '').trim();
} catch (e) {
  theme = '';
}

const companies = Array.isArray(data.companies) ? data.companies : [];
const you = companies.find((c) => c.is_you);
const gaps = Array.isArray(data.gaps) ? data.gaps : [];

// What the last run stored, keyed on the employer id rather than the name: a
// company that rebrands is still the same row. On the first run the table is
// empty and the read emits one blank item, which the guard drops.
const history = new Map();
for (const item of $('Read The Last Run').all()) {
  const row = (item && item.json) || {};
  if (row.employer_id) history.set(String(row.employer_id), row);
}

function movement(c) {
  const prior = history.get(String(c.employer_id));
  if (!prior) return '';
  const was = Number(prior.overall);
  const now = c.scores.rating_overall.all;
  if (!Number.isFinite(was) || now === null) return '';
  const when = String(prior.checked_on || '').slice(0, 10);
  const delta = Math.round((now - was) * 100) / 100;
  if (delta === 0) return `    overall unchanged since ${when}`;
  const way = delta > 0 ? 'up' : 'down';
  return `    overall ${way} ${Math.abs(delta).toFixed(2)} since ${when}, from ${was.toFixed(2)}`;
}

function plural(n, one, many) {
  return `${n} ${n === 1 ? one : many}`;
}

function num(v) {
  return v === null || v === undefined ? '-' : v.toFixed(2);
}

const lines = [];
lines.push('*Employer brand benchmark*');
lines.push(`Every company cut to the same window, ${data.window_from} to ${data.window_to}, because Glassdoor returns 100 reviews whatever you ask for and each company's hundred covers a different stretch.`);

// The shared window is as short as the most-reviewed company's hundred, so a
// quieter competitor can end up contributing a dozen reviews to it. The gaps
// below are still the right comparison - they are just being read off a small
// sample, and saying so costs one line.
const thin = companies.filter((c) => c.reviews_in_window < 25);
if (thin.length) {
  lines.push(`_Small sample: ${thin.map((c) => `${c.company} has ${c.reviews_in_window}`).join(', ')} inside that window. Under about 25 reviews one bad month moves the average, so treat the gaps below as a signal rather than a measurement._`);
}
lines.push('');

for (const c of companies) {
  const tag = c.is_you ? ' (you)' : '';
  lines.push(`*${c.company}${tag}* - ${plural(c.reviews_in_window, 'review', 'reviews')} in window, of ${c.reviews_total} pulled (${c.span_from} to ${c.span_to})`);
  lines.push(`    overall ${num(c.scores.rating_overall.all)} | pay ${num(c.scores.rating_compensation_benefits.all)} | culture ${num(c.scores.rating_culture_values.all)} | work-life ${num(c.scores.rating_work_life.all)} | leadership ${num(c.scores.rating_senior_leadership.all)}`);
  const cur = c.scores.rating_overall.current;
  const fmr = c.scores.rating_overall.former;
  if (cur !== null && fmr !== null) {
    lines.push(`    current staff ${num(cur)} (${c.current_count}) vs former ${num(fmr)} (${c.former_count})`);
  }
  if (c.would_recommend) {
    lines.push(`    would recommend ${c.would_recommend.pct}% of the ${c.would_recommend.answered} who answered`);
  }
  const moved = movement(c);
  if (moved) {
    lines.push(moved);
  }
  lines.push('');
}

if (gaps.length && you) {
  lines.push('*Where you are furthest behind*');
  for (const g of gaps.slice(0, 3)) {
    if (g.gap <= 0) continue;
    lines.push(`• ${g.label}: you ${num(g.yours)}, ${g.best_rival_name} ${num(g.best_rival)} - ${g.gap.toFixed(2)} behind`);
  }
  const ahead = gaps.filter((g) => g.gap < 0);
  if (ahead.length) {
    lines.push(`_Ahead on ${ahead.map((g) => g.label.toLowerCase()).join(', ')}._`);
  }
  lines.push('');
}

if (theme) {
  lines.push(`*What your own reviewers say about ${(data.worst_label || '').toLowerCase()}*`);
  lines.push(theme);
  lines.push('');
}

if ((data.missing || []).length) {
  lines.push(`_No reviews came back for: ${data.missing.map((m) => m.url).join(', ')}. Check the employer id after the E._`);
}
if ((data.errors || []).length) {
  lines.push(`_Crawl errors: ${data.errors.slice(0, 2).join('; ')}_`);
}

// Every column is text. A dimension nobody answered has no score, and an empty
// string into a number column is rejected outright - so the table takes the
// formatted number and the reader turns it back.
function cell(v) {
  return v === null || v === undefined ? '' : String(v);
}

const checked = new Date().toISOString().slice(0, 10);
const rows = companies.map((c) => ({
  employer_id: c.employer_id,
  company: c.company,
  is_you: c.is_you ? 'yes' : 'no',
  checked_on: checked,
  window_from: data.window_from,
  window_to: data.window_to,
  reviews_in_window: String(c.reviews_in_window),
  overall: cell(c.scores.rating_overall.all),
  pay: cell(c.scores.rating_compensation_benefits.all),
  culture: cell(c.scores.rating_culture_values.all),
  work_life: cell(c.scores.rating_work_life.all),
  leadership: cell(c.scores.rating_senior_leadership.all),
  career: cell(c.scores.rating_career_opportunities.all),
  diversity: cell(c.scores.rating_diversity_inclusion.all),
  would_recommend_pct: c.would_recommend ? String(c.would_recommend.pct) : '',
}));

// One item per company so the upsert keeps one row each, moving, rather than a
// new row per run that nobody can read a trend out of.
return [{ json: { message: lines.join('\n'), rows, row_count: rows.length } }];

